import {createEmptyProject} from '../../src/projectLifecycle.js';
import {installLockedDoor} from '../../src/componentExamples.js';
import {addMechanicInstance} from '../../src/mechanicDescriptions.js';
import {reference} from '../../src/valueSchemas.js';
export const call=(id,methodId,args={})=>({id:'sacura.component.call',version:1,parameters:{instance:reference('mechanic',id),methodId,args}});
export function doors(){const p=createEmptyProject('Две двери'),scene=p.subscenes[0];p.gameplay.storyPolicy={mode:'story',mechanics:'continuous',dialogueControl:'allow',ending:'continue'};for(const [id,name,pos]of [['door-a','Дверь склада',[-2,1,0]],['door-b','Дверь архива',[2,1,0]]])p.objects.push({id,name,type:'Активный меш',active:true,subsceneId:scene.id,primitive:'box',color:'#94785b',transforms:{[scene.id]:{position:pos,rotation:[0,0,0],scale:[1,2,.2]}}});const d=installLockedDoor(p),a=addMechanicInstance(p,d.id,{kind:'object',id:'door-a'}),b=addMechanicInstance(p,d.id,{kind:'object',id:'door-b'});for(const m of [a,b]){m.values.OpenSeconds=.1;p.objects.find(o=>o.id===m.scope.id).interactionCall=call(m.id,'interact');}const first=p.chapters[0].beats[0];first.text='Двери заперты';first.next='second';p.chapters[0].beats.push({id:'second',kind:'dialogue',speaker:'Рассказчик',text:'Разрешено открыть склад',next:'third',bindings:[]},{id:'third',kind:'dialogue',speaker:'Рассказчик',text:'Следующая реплика',next:null,bindings:[]});return {p,a,b,d,first};}
